import heapq
n = len(grid)
ans = [float('inf')] * k
queue = []
for i in range(n):
    for j in range(n):
        if grid[i][j] == 1:
            queue.append((1, [1], i, j))
while queue:
    cur, cur_list, cur_i, cur_j = heapq.heappop(queue)
    if len(cur_list) == k:
        if cur_list < ans:
            ans = cur_list
        continue
    for next_i, next_j in [(cur_i + 1, cur_j), (cur_i - 1, cur_j), (cur_i, cur_j + 1), (cur_i, cur_j - 1)]:
        if 0 <= next_i < n and 0 <= next_j < n:
            heapq.heappush(queue, (grid[next_i][next_j], cur_list + [grid[next_i][next_j]], next_i, next_j))
return ans

